/**
 * @file Points barrel imports at each component's own file.
 *
 * Astro makes an island's import specifier its hydration entry. `import { Select } from '@splendidlabz/svelte'` makes the whole barrel the entry, so every island downloads every component. Rewriting the import to the component's own file before Astro compiles it gives each island only what it uses.
 *
 * The rewrite runs in `load`, since Astro compiles `.astro` in a `pre` transform ordered ahead of any integration's plugin.
 */

import { existsSync, readFileSync, realpathSync, statSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'

/**
 * @import { ViteUserConfig } from 'astro'
 */

/**
 * unbarrel
 * Rewrites a package's barrel imports in `.astro` and `.mdx` files.
 *
 * @typedef {NonNullable<ViteUserConfig['plugins']>[number]} Plugin Vite resolves only inside astro's own node_modules.
 *
 * @param {object} opts
 * @param {string} opts.root The site's root folder.
 * @param {string} opts.pkg Package whose barrel is rewritten.
 * @returns {Plugin}
 */
export function unbarrel({ root, pkg }) {
  const barrel = findBarrel({ root, pkg })

  // A site that doesn't install the package has nothing to rewrite
  if (!barrel) return { name: 'splendid:unbarrel' }

  const components = getBarrelComponents(barrel)

  return {
    name: 'splendid:unbarrel',
    enforce: 'pre',
    load(id) {
      if (!/\.(astro|mdx)$/.test(id)) return

      const code = readFileSync(id, 'utf8')
      if (!code.includes(pkg)) return

      const rewritten = id.endsWith('.mdx')
        ? rewriteMdx({ code, pkg, components })
        : rewriteAstro({ code, pkg, components })

      if (rewritten !== code) return rewritten
    },
  }
}

/**
 * rewriteAstro
 * Rewrites barrel imports in an `.astro` file's frontmatter.
 *
 * The template is left alone, so a code sample showing the import stays as written.
 *
 * @param {object} opts
 * @param {string} opts.code
 * @param {string} opts.pkg
 * @param {Record<string, string>} opts.components Export name to component file.
 * @returns {string}
 */
export function rewriteAstro({ code, pkg, components }) {
  const frontmatter = code.match(/^(\s*---\r?\n)([\s\S]*?)(\r?\n---)/)
  if (!frontmatter) return code

  const [whole, open, body, close] = frontmatter
  const rewritten = rewriteImports({ code: body, pkg, components })

  return open + rewritten + close + code.slice(whole.length)
}

/**
 * rewriteMdx
 * Rewrites barrel imports in an `.mdx` file, outside code fences.
 *
 * @param {object} opts
 * @param {string} opts.code
 * @param {string} opts.pkg
 * @param {Record<string, string>} opts.components Export name to component file.
 * @returns {string}
 */
export function rewriteMdx({ code, pkg, components }) {
  // Splits on fences; odd indexes are the fences themselves
  const parts = code.split(/(^(`{3,}|~{3,})[^\n]*\n[\s\S]*?^\2[ \t]*$)/m)

  return parts
    .map((part, index) => {
      // The split's inner group repeats each fence's marker, which carries no text
      if (index % 3 === 2) return ''
      if (index % 3 === 1) return part
      return rewriteImports({ code: part, pkg, components })
    })
    .join('')
}

/**
 * rewriteImports
 * Turns each named barrel import into default imports of component files.
 *
 * Names that aren't components stay on a barrel import. The line count is kept, so errors still point at the right line.
 *
 * @param {object} opts
 * @param {string} opts.code
 * @param {string} opts.pkg
 * @param {Record<string, string>} opts.components Export name to component file.
 * @returns {string}
 */
function rewriteImports({ code, pkg, components }) {
  const escaped = pkg.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')
  const statement = new RegExp(
    `^import\\s*\\{([^}]*)\\}\\s*from\\s*(['"])${escaped}\\2;?`,
    'gm',
  )

  return code.replace(statement, (whole, list) => {
    const specifiers = list
      .split(',')
      .map(specifier => specifier.trim())
      .filter(Boolean)
      .map(specifier => {
        const [imported, local = imported] = specifier.split(/\s+as\s+/)
        return { imported, local, specifier }
      })

    const direct = specifiers
      .filter(({ imported }) => components[imported])
      .map(
        ({ imported, local }) =>
          `import ${local} from ${JSON.stringify(components[imported])};`,
      )

    const kept = specifiers
      .filter(({ imported }) => !components[imported])
      .map(({ specifier }) => specifier)

    if (kept.length) direct.push(`import { ${kept.join(', ')} } from '${pkg}';`)

    const newlines = '\n'.repeat(whole.split('\n').length - 1)
    return direct.join(' ') + newlines
  })
}

/**
 * findBarrel
 * Finds the file a package's `svelte` export condition points at.
 *
 * @param {object} opts
 * @param {string} opts.root
 * @param {string} opts.pkg
 * @returns {string | null} Null when the package isn't installed.
 */
function findBarrel({ root, pkg }) {
  let dir = root

  // Walks up, the way Node looks for node_modules
  while (!existsSync(join(dir, 'node_modules', pkg))) {
    if (dir === dirname(dir)) return null
    dir = dirname(dir)
  }

  const pkgDir = realpathSync(join(dir, 'node_modules', pkg))
  const { exports } = JSON.parse(
    readFileSync(join(pkgDir, 'package.json'), 'utf8'),
  )

  return join(pkgDir, exports['.'].svelte)
}

/**
 * getBarrelComponents
 * Maps each `.svelte` component a barrel exports to its file.
 *
 * Follows `export *` into nested barrels. Reads the four forms the Splendid barrels use: `export *`, `export { default as X } from`, and `import X from` paired with `export { X }`.
 *
 * @param {string} file A barrel file, or a folder holding `index.js`.
 * @returns {Record<string, string>} Export name to absolute file.
 */
export function getBarrelComponents(file) {
  const barrel = toModuleFile(file)
  const dir = dirname(barrel)
  const code = readFileSync(barrel, 'utf8')

  /** @type {Record<string, string>} */
  const components = {}

  for (const [, from] of code.matchAll(
    /^export\s*\*\s*from\s*['"](.+?)['"]/gm,
  )) {
    Object.assign(components, getBarrelComponents(resolve(dir, from)))
  }

  for (const [, list, from] of code.matchAll(
    /^export\s*\{([^}]*)\}\s*from\s*['"](.+?)['"]/gm,
  )) {
    for (const specifier of list.split(',')) {
      const [imported, local] = specifier.trim().split(/\s+as\s+/)
      if (imported === 'default' && from.endsWith('.svelte')) {
        components[local] = resolve(dir, from)
      }
    }
  }

  // Default imports of components, exported by name further down
  /** @type {Record<string, string>} */
  const imported = {}
  for (const [, name, from] of code.matchAll(
    /^import\s+(\w+)\s+from\s*['"](.+?\.svelte)['"]/gm,
  )) {
    imported[name] = resolve(dir, from)
  }

  for (const [, list] of code.matchAll(/^export\s*\{([^}]*)\}\s*;?\s*$/gm)) {
    for (const specifier of list.split(',')) {
      const [name, exported = name] = specifier.trim().split(/\s+as\s+/)
      if (imported[name]) components[exported] = imported[name]
    }
  }

  return components
}

/**
 * toModuleFile
 * Resolves a barrel path the way a bundler reads `./Folder` or `./file`.
 *
 * @param {string} file
 * @returns {string}
 */
function toModuleFile(file) {
  if (existsSync(file) && statSync(file).isDirectory()) {
    return join(file, 'index.js')
  }
  if (!existsSync(file)) return `${file}.js`
  return file
}
